insert into public.kb_items (id, question, answer, answer_key, source_id, topics, alt_questions, aliases, phrases, status, audience, confidence, conservative, verified_on, verified_by, review_legal, review_clinical, review_marketing, version)
values ('K101', 'What services do you offer?', 'We offer non-medical home care at three levels. Wellness Care is companionship, meals, light housekeeping, errands, rides and medication reminders. Personal Care adds hands-on help with bathing, dressing, toileting and getting around. Advanced Care is for advanced dementia, wandering or significant mobility needs. We also do Overnight Care, 24-Hour Care, Respite Care, help after a hospital stay, and HomeTogether TV video check-ins. You can move between levels without changing agencies.', 'services_overview', 'S7', array['services','home care','care','offer']::text[], array['What kind of care do you provide?','What types of care do you offer?','What do you help with?']::text[], array[]::text[], array[]::text[], 'verified', 'public', 95, false, '2026-10-27', 'mo-care.com live pages (Claude, her ask 10-27)', 'na', 'na', 'ok', 1)
