insert into public.kb_items (id, question, answer, answer_key, source_id, topics, alt_questions, aliases, phrases, status, audience, confidence, conservative, verified_on, verified_by, review_legal, review_clinical, review_marketing, version)
values ('K104', 'Do you accept Medicaid?', 'Caring Companions does not take Medicaid. For Medicaid-funded care at home, please reach our sister company, Caring Companions Consumer Directed Services, at (417) 218-2888 or caringcds.com. They can talk you through Consumer Directed Services, where the person receiving care chooses their own attendant.', 'medicaid', 'S7', array['medicaid','accept','mo healthnet','cds']::text[], array['Does Medicaid pay for your care?','Can we use Medicaid?','Do you take MO HealthNet?','Is Medicaid accepted?']::text[], array[]::text[], array[]::text[], 'verified', 'public', 95, false, '2026-10-27', 'mo-care.com live pages (Claude, her ask 10-27)', 'na', 'na', 'ok', 1)
