insert into public.kb_items (id, question, answer, answer_key, source_id, topics, alt_questions, aliases, phrases, status, audience, confidence, conservative, verified_on, verified_by, review_legal, review_clinical, review_marketing, version)
values ('K105', 'How can we pay for care?', 'There are a few ways to pay. Private pay is billed directly at our published rates. We work with VA benefits, including Community Care and Aid and Attendance. We verify and bill long-term care insurance policies. Medicare GUIDE covers dementia respite visits for eligible families. We do not take Medicaid. For Medicaid, please reach our sister company, Caring Companions Consumer Directed Services, at (417) 218-2888 or caringcds.com.', 'ways_to_pay', 'S7', array['pay','payment','accept','insurance','private pay','va','long term care insurance','medicare']::text[], array['What payment do you accept?','Do you take insurance?','What are the ways to pay?','Do you accept private pay?']::text[], array[]::text[], array[]::text[], 'verified', 'public', 95, false, '2026-10-27', 'mo-care.com live pages (Claude, her ask 10-27)', 'na', 'na', 'ok', 1)
