insert into public.kb_items (id, question, answer, answer_key, source_id, topics, alt_questions, aliases, phrases, status, audience, confidence, conservative, verified_on, verified_by, review_legal, review_clinical, review_marketing, version)
values ('K106', 'Does Medicare pay for home care?', 'The Medicare program we work with is GUIDE, for people living with dementia at home. Families further along in the disease can get 20 four-hour respite visits a year, billed to Medicare. Medicare decides who qualifies. Caring Companions is an approved GUIDE respite provider in southwest Missouri. Call (417) 234-8494 and we will check eligibility with you.', 'medicare_guide', 'S7', array['medicare','guide','dementia','respite']::text[], array['What is the Medicare GUIDE program?','Does Medicare cover dementia respite?','Can Medicare pay for a caregiver?']::text[], array[]::text[], array[]::text[], 'verified', 'public', 95, false, '2026-10-27', 'mo-care.com live pages (Claude, her ask 10-27)', 'na', 'na', 'ok', 1)
