insert into public.kb_items (id, question, answer, answer_key, source_id, topics, alt_questions, aliases, phrases, status, audience, confidence, conservative, verified_on, verified_by, review_legal, review_clinical, review_marketing, version)
values ('K107', 'Do you work with VA benefits?', 'Yes. We work with VA benefits, including VA Community Care and Aid and Attendance. Community Care is arranged through the veteran''s VA primary care team. Call (417) 234-8494 and a care coordinator can talk through what fits.', 'va_benefits', 'S7', array['va','veteran','aid and attendance','benefits']::text[], array['Does the VA pay for home care?','My dad is a veteran, can the VA help?','Do you accept Aid and Attendance?']::text[], array[]::text[], array[]::text[], 'verified', 'public', 95, false, '2026-10-27', 'mo-care.com live pages (Claude, her ask 10-27)', 'na', 'na', 'ok', 1)
