insert into public.kb_items (id, question, answer, answer_key, source_id, topics, alt_questions, aliases, phrases, status, audience, confidence, conservative, verified_on, verified_by, review_legal, review_clinical, review_marketing, version)
values ('K108', 'Do you take long-term care insurance?', 'Yes. We verify your benefits, set up a call with your carrier, help with the claim forms, and can bill the insurance company directly or give you paid invoices to submit. Most policies pay once help is needed with 2 or more daily activities, or with a cognitive impairment. We review your policy with you before you commit to anything.', 'ltc_insurance', 'S7', array['long term care insurance','ltc','policy','insurance']::text[], array['Will my long-term care policy pay for this?','Can you bill my LTC insurance?']::text[], array[]::text[], array[]::text[], 'verified', 'public', 95, false, '2026-10-27', 'mo-care.com live pages (Claude, her ask 10-27)', 'na', 'na', 'ok', 1)
