insert into public.kb_items (id, question, answer, answer_key, source_id, topics, alt_questions, aliases, phrases, status, audience, confidence, conservative, verified_on, verified_by, review_legal, review_clinical, review_marketing, version)
values ('K109', 'What area do you serve?', 'We are based in Springfield. We actively serve Greene, Christian, Webster and Polk counties. In Taney, Lawrence, Dallas and Stone counties we start care when we have a caregiver nearby and enough weekly hours to keep care steady, so please call first. You can check your ZIP code on mo-care.com/service-area or call (417) 234-8494.', 'service_area', 'S7', array['area','county','serve','town','springfield','zip']::text[], array['Do you serve my town?','What counties do you cover?','Are you near me?','Do you come to Branson?']::text[], array[]::text[], array[]::text[], 'verified', 'public', 95, false, '2026-10-27', 'mo-care.com live pages (Claude, her ask 10-27)', 'na', 'na', 'ok', 1)
