insert into public.kb_items (id, question, answer, answer_key, source_id, topics, alt_questions, aliases, phrases, status, audience, confidence, conservative, verified_on, verified_by, review_legal, review_clinical, review_marketing, version)
values ('K110', 'How do we get started?', 'It starts with an in-home assessment. An experienced care coordinator comes to the home for about an hour and a half, meets your loved one, and builds a care plan with you. There is no charge and no obligation. You can book it at mo-care.com/book or call (417) 234-8494. If you would rather start online, the Care Questionnaire takes about 8 minutes.', 'getting_started', 'S7', array['assessment','start','first step','book','consultation']::text[], array['How does getting started work?','What is the first step?','How do I set up care?','How do I sign up?','Can we schedule an assessment?']::text[], array[]::text[], array[]::text[], 'verified', 'public', 95, false, '2026-10-27', 'mo-care.com live pages (Claude, her ask 10-27)', 'na', 'na', 'ok', 1)
