insert into public.kb_items (id, question, answer, answer_key, source_id, topics, alt_questions, aliases, phrases, status, audience, confidence, conservative, verified_on, verified_by, review_legal, review_clinical, review_marketing, version)
values ('K112', 'Do you offer overnight care?', 'Yes. A caregiver comes in the evening and stays through the night, usually an 8 to 12 hour shift, to help with bathroom trips, wandering, medication reminders or anything after dark. It is $30 to $34 an hour depending on the level of care, as many nights a week as you need.', 'overnight_care', 'S7', array['overnight','night','nights']::text[], array['Can someone stay at night?','Do you have night shifts for clients?','Can a caregiver stay overnight?']::text[], array[]::text[], array[]::text[], 'verified', 'public', 95, false, '2026-10-27', 'mo-care.com live pages (Claude, her ask 10-27)', 'na', 'na', 'ok', 1)
