insert into public.kb_items (id, question, answer, answer_key, source_id, topics, alt_questions, aliases, phrases, status, audience, confidence, conservative, verified_on, verified_by, review_legal, review_clinical, review_marketing, version)
values ('K113', 'Do you offer 24-hour care?', 'Yes, through 24-Hour Care. Caregivers work rotating shifts, usually two 12-hour or three 8-hour shifts a day, so someone awake is always there. We do not offer live-in care. 24-Hour Care is billed hourly at $30 to $34 an hour depending on the level of care.', 'round_the_clock', 'S7', array['24 hour','around the clock','live in','24 7']::text[], array['Can someone be there around the clock?','Do you offer live-in care?','Can she have a caregiver 24/7?']::text[], array[]::text[], array[]::text[], 'verified', 'public', 95, false, '2026-10-27', 'mo-care.com live pages (Claude, her ask 10-27)', 'na', 'na', 'ok', 1)
