insert into public.kb_items (id, question, answer, answer_key, source_id, topics, alt_questions, aliases, phrases, status, audience, confidence, conservative, verified_on, verified_by, review_legal, review_clinical, review_marketing, version)
values ('K114', 'Do you offer respite care?', 'Yes. Respite care gives a family caregiver time off while one of our caregivers steps in. It can be a regular shift, daily, weekly or monthly, from 4 to 24 hours, or as needed when something comes up. Respite visits can include an outing too. For families caring for someone with dementia, the Medicare GUIDE program may cover respite visits.', 'respite_care', 'S7', array['respite','break','relief','family caregiver']::text[], array['I need a break from caregiving','Can someone give me relief?','Can you cover while I am away?']::text[], array[]::text[], array[]::text[], 'verified', 'public', 95, false, '2026-10-27', 'mo-care.com live pages (Claude, her ask 10-27)', 'na', 'na', 'ok', 1)
