insert into public.kb_items (id, question, answer, answer_key, source_id, topics, alt_questions, aliases, phrases, status, audience, confidence, conservative, verified_on, verified_by, review_legal, review_clinical, review_marketing, version)
values ('K115', 'Do you provide nursing or medical care?', 'No. Our care is non-medical. Our caregivers help with daily living, personal care, dementia support and safety at home, but we do not provide skilled nursing.', 'not_medical', 'S7', array['nurse','nursing','medical','skilled']::text[], array['Do you have nurses?','Can your caregivers do medical care?','Do you do skilled nursing?']::text[], array[]::text[], array[]::text[], 'verified', 'public', 95, false, '2026-10-27', 'mo-care.com live pages (Claude, her ask 10-27)', 'na', 'na', 'ok', 1)
