values ('K118', 'How do I reach your office?', 'Call (417) 234-8494. A real person answers 24 hours a day, 7 days a week, including nights, weekends and holidays. Our office is at 1331 N Stewart Ave, Suite B, Springfield, MO 65802.', 'contact', 'S7', array['phone','call','office','address','contact']::text[], array['What is your phone number?','Where are you located?','Can I talk to a person?','What are your office hours?']::text[], array[]::text[], array[]::text[], 'verified', 'public', 95, false, '2026-10-27', 'mo-care.com live pages (Claude, her ask 10-27)', 'na', 'na', 'ok', 1)
