values ('K119', 'Is HomeTogether TV included with care?', 'Yes. Families who receive 20 or more hours of care a week get HomeTogether TV included at no extra cost. It brings video calls, reminders and quiet safety monitoring to the TV they already watch.', 'hometogether_included', 'S7', array['hometogether','tv','included','20 hours']::text[], array['Do clients get HomeTogether?','Is the TV device included with 20 hours?']::text[], array[]::text[], array[]::text[], 'verified', 'public', 95, false, '2026-10-27', 'mo-care.com live pages (Claude, her ask 10-27)', 'na', 'na', 'ok', 1)
