values ('K128', 'Do you help with bathing and personal care?', 'Yes. Personal Care is $32 an hour and includes everything in Wellness Care plus bathing and showering, dressing and grooming, toileting and incontinence care, help walking, safe transfers and help with eating.', 'personal_care', 'S7', array['personal care','bathing','dressing','toileting','pca']::text[], array['What is personal care?','Can you help with showers and dressing?','Do you offer PCA services?']::text[], array[]::text[], array[]::text[], 'verified', 'public', 95, false, '2026-10-27', 'mo-care.com live pages (Claude, her ask 10-27)', 'na', 'na', 'ok', 1)
