insert into public.kb_items (id, question, answer, answer_key, source_id, topics, alt_questions, aliases, phrases, status, audience, confidence, conservative, verified_on, verified_by, review_legal, review_clinical, review_marketing, version)
values ('K130', 'Can you help when someone comes home from the hospital?', 'Yes. The first days home from a hospital or rehab carry the highest risk of a fall, so many families start with Personal Care, $32 an hour, and taper as their loved one recovers. Some choose Overnight or 24-Hour Care for the first stretch. Call (417) 234-8494 and we will talk through what fits.', 'hospital_recovery', 'S7', array['hospital','rehab','discharge','surgery','coming home']::text[], array['My dad is being discharged from rehab','Do you help after surgery?']::text[], array[]::text[], array[]::text[], 'verified', 'public', 95, false, '2026-10-27', 'mo-care.com live pages (Claude, her ask 10-27)', 'na', 'na', 'ok', 1)
